    result.shape = ['rect', 'ellipse', 'line', 'path'].includes(layer?.shape) ? layer.shape : 'rect';
    result.fill = shortText(layer?.fill, '#4f8cff', 64);
    result.stroke = shortText(layer?.stroke, 'transparent', 64);
